import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"27、【颐】 震下艮上","description":"横渠易说 - 27、【颐】 震下艮上","frontmatter":{"title":"27、【颐】 震下艮上","description":"横渠易说 - 27、【颐】 震下艮上"},"headers":[],"relativePath":"zh/classics/hengqu/029.md","filePath":"zh/classics/hengqu/029.md"}'),l={name:"zh/classics/hengqu/029.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_27、【颐】-震下艮上" tabindex="-1">27、【颐】 震下艮上 <a class="header-anchor" href="#_27、【颐】-震下艮上" aria-label="Permalink to “27、【颐】 震下艮上”">​</a></h1><h3 id="彖曰-颐贞吉-养正则吉也。-观颐-观其所养也-自求口实-观其自养也。天地养万物-圣人养贤以及万民-颐之时大矣哉" tabindex="-1">彖曰：“颐贞吉”，养正则吉也。“观颐”，观其所养也；“自求口实”，观其自养也。天地养万物，圣人养贤以及万民，颐之时大矣哉! <a class="header-anchor" href="#彖曰-颐贞吉-养正则吉也。-观颐-观其所养也-自求口实-观其自养也。天地养万物-圣人养贤以及万民-颐之时大矣哉" aria-label="Permalink to “彖曰：“颐贞吉”，养正则吉也。“观颐”，观其所养也；“自求口实”，观其自养也。天地养万物，圣人养贤以及万民，颐之时大矣哉!”">​</a></h3><p>观颐，辨养道得失，欲观人处己之方。</p><h3 id="象曰-山下有雷-颐-君子以慎言语-节饮食。" tabindex="-1">象曰：山下有雷，颐，君子以慎言语，节饮食。 <a class="header-anchor" href="#象曰-山下有雷-颐-君子以慎言语-节饮食。" aria-label="Permalink to “象曰：山下有雷，颐，君子以慎言语，节饮食。”">​</a></h3><p>山下有雷，畜养之象。</p><h3 id="初九-舍尔灵龟-观我朵颐-凶。-象曰-观我朵颐-亦不足贵也。" tabindex="-1">初九，舍尔灵龟，观我朵颐，凶。 象曰：“观我朵颐”，亦不足贵也。 <a class="header-anchor" href="#初九-舍尔灵龟-观我朵颐-凶。-象曰-观我朵颐-亦不足贵也。" aria-label="Permalink to “初九，舍尔灵龟，观我朵颐，凶。 象曰：“观我朵颐”，亦不足贵也。”">​</a></h3><p>体躁应上，观我而朵其颐，求养而无耻者也。</p><h3 id="六二-颠颐拂经-于丘颐-征凶。-象曰-六二征凶-行失类也。" tabindex="-1">六二，颠颐拂经，于丘颐，征凶。 象曰：六二征凶，行失类也。 <a class="header-anchor" href="#六二-颠颐拂经-于丘颐-征凶。-象曰-六二征凶-行失类也。" aria-label="Permalink to “六二，颠颐拂经，于丘颐，征凶。 象曰：六二征凶，行失类也。”">​</a></h3><p>凡颐之正，以贵养贱，以阳养阴，所谓经也。颐卦群阴皆当听养于上，六二违之，反比于初，以阴养阳，颠颐者也。群阴，上所聚养者也，六二乱经于聚养之义，失阴类之常，故以进则凶。</p><h3 id="六三-拂颐-贞凶。十年勿用-无攸利。-象曰-十年勿用-道大悖也。" tabindex="-1">六三，拂颐，贞凶。十年勿用，无攸利。 象曰：“十年勿用”，道大悖也。 <a class="header-anchor" href="#六三-拂颐-贞凶。十年勿用-无攸利。-象曰-十年勿用-道大悖也。" aria-label="Permalink to “六三，拂颐，贞凶。十年勿用，无攸利。 象曰：“十年勿用”，道大悖也。”">​</a></h3><p>履邪好动，系说于上，不但拂经而已，害颐之正莫甚焉，故凶。“系说于上”一作“系而说上”。</p><h3 id="六四-颠颐-吉。虎视眈眈-其欲逐逐-无咎。-象曰-颠颐之吉-上施光也。" tabindex="-1">六四，颠颐，吉。虎视眈眈，其欲逐逐，无咎。 象曰：颠颐之吉，上施光也。 <a class="header-anchor" href="#六四-颠颐-吉。虎视眈眈-其欲逐逐-无咎。-象曰-颠颐之吉-上施光也。" aria-label="Permalink to “六四，颠颐，吉。虎视眈眈，其欲逐逐，无咎。 象曰：颠颐之吉，上施光也。”">​</a></h3><p>体顺位阴，得颐之正，以贵养贱而得贤者，虽反阳爻养阴之义，以上养下，其施光矣。然以柔养刚，非严重其德，广大其志，则未免于咎。</p><h3 id="六五-拂经-居贞吉。不可涉大川。-象曰-居贞之吉-顺以从上也。" tabindex="-1">六五，拂经，居贞吉。不可涉大川。 象曰：居贞之吉，顺以从上也。 <a class="header-anchor" href="#六五-拂经-居贞吉。不可涉大川。-象曰-居贞之吉-顺以从上也。" aria-label="Permalink to “六五，拂经，居贞吉。不可涉大川。 象曰：居贞之吉，顺以从上也。”">​</a></h3><p>听养于上，正也；以阴居颐卦之尊，拂经也。</p><h3 id="上九-由颐-厉吉-利涉大川。-象曰-由颐厉吉-大有庆也。" tabindex="-1">上九，由颐，厉吉，利涉大川。 象曰：“由颐厉吉”，大有庆也。 <a class="header-anchor" href="#上九-由颐-厉吉-利涉大川。-象曰-由颐厉吉-大有庆也。" aria-label="Permalink to “上九，由颐，厉吉，利涉大川。 象曰：“由颐厉吉”，大有庆也。”">​</a></h3><p>由颐自危然后乃吉者，下有众阴顺从之庆，骄则有它吝。此卦得养之正者方利涉大川，盖养然后可动耳。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
